9	func runPartitionedSliding(t *testing.T, input string, window, slide, partitions int64) (string, string, error) {
10		t.Helper()
11		var stdout, stderr bytes.Buffer
12		err := RunAggregatePartitionedSliding(strings.NewReader(input), window, slide, partitions, &stdout, &stderr)
13		return stdout.String(), stderr.String(), err
