16	// Sliding windows combine with partitions: the same key from different
17	// partitions merges within each overlapping window, and only the effective
18	// (minimum) watermark closes them.
19	func TestAggregatePartitionedSlidingMergesPerWindow(t *testing.T) {
20		input := strings.Join([]string{
21			`{"type":"event","key":"k","time":700,"value":2,"partition":0}`,
22			`{"type":"event","key":"k","time":1000,"value":3,"partition":1}`,
23			`{"type":"watermark","time":5000,"partition":0}`, // ahead: effective still unknown
24			`{"type":"watermark","time":1000,"partition":1}`, // min = 1000: closes only [0,1000)
25			`{"type":"watermark","time":5000,"partition":0}`, // p0 repeats; min stays 1000
26			`{"type":"watermark","time":1600,"partition":1}`, // min = 1600: closes [600,1600)
27		}, "\n")
28		stdout, stderr, err := runPartitionedSliding(t, input, 1000, 600, 2)
29		if err != nil {
30			t.Fatalf("unexpected error: %v", err)
31		}
32		if stderr != "" {
33			t.Fatalf("unexpected stderr: %q", stderr)
34		}
35		want := strings.Join([]string{
36			`{"key":"k","start":0,"end":1000,"count":1,"sum":2}`,
37			`{"key":"k","start":600,"end":1600,"count":2,"sum":5}`,
38			``,
39		}, "\n")
40		if stdout != want {
41			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
42		}
43	}
44	
45	// The late-event check uses the effective watermark: an event below the min
46	// is skipped entirely even while an overlapping window covering its time is
47	// still open.
48	func TestAggregatePartitionedSlidingLateUsesEffectiveWatermark(t *testing.T) {
49		input := strings.Join([]string{
50			`{"type":"watermark","time":5000,"partition":0}`,
51			`{"type":"watermark","time":1000,"partition":1}`,                // effective = 1000
52			`{"type":"event","key":"k","time":999,"value":1,"partition":0}`, // late despite open [600,1600)
53			`{"type":"event","key":"k","time":1000,"value":4,"partition":0}`,
54			`{"type":"watermark","time":1600,"partition":1}`,
55		}, "\n")
56		stdout, stderr, err := runPartitionedSliding(t, input, 1000, 600, 2)
57		if err != nil {
58			t.Fatalf("unexpected error: %v", err)
59		}
60		want := `{"key":"k","start":600,"end":1600,"count":1,"sum":4}` + "\n"
61		if stdout != want {
62			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
63		}
64		wantErr := "line 3: late event time=999 below current watermark 1000, skipped\n"
65		if stderr != wantErr {
66			t.Fatalf("stderr = %q, want %q", stderr, wantErr)
67		}
68	}
