70	// Before the effective watermark exists nothing closes and nothing is late;
71	// an idle declaration can itself close overlapping windows.
72	func TestAggregatePartitionedSlidingIdleCloses(t *testing.T) {
73		input := strings.Join([]string{
74			`{"type":"event","key":"k","time":700,"value":2,"partition":0}`,
75			`{"type":"event","key":"k","time":1000,"value":3,"partition":0}`,
76			`{"type":"watermark","time":1600,"partition":0}`,
77			`{"type":"idle","partition":1}`, // effective = 1600: [0,1000) and [600,1600) close
78		}, "\n")
79		stdout, _, err := runPartitionedSliding(t, input, 1000, 600, 2)
80		if err != nil {
81			t.Fatalf("unexpected error: %v", err)
82		}
83		want := strings.Join([]string{
84			`{"key":"k","start":0,"end":1000,"count":1,"sum":2}`,
85			`{"key":"k","start":600,"end":1600,"count":2,"sum":5}`,
86			``,
87		}, "\n")
88		if stdout != want {
89			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
90		}
